// Worker entry (wrangler.jsonc "main"): the OpenNext app, plus the cron trigger that sweeps stale render jobs.
// `.open-next/worker.js` is generated by `npm run cf:build`; this file only wraps it (OpenNext "custom worker").
import handler from "./.open-next/worker.js";

/** Where the sweep runs as. Webhook URLs minted by a sweep-time auto-retry use this origin. */
const DEFAULT_ORIGIN = "https://valora3d.com";

const worker = {
  fetch: handler.fetch,

  /**
   * Every few minutes (wrangler.jsonc "triggers.crons"): re-poll render jobs nobody has heard from, so a lost
   * RunPod webhook or a dropped submission still ends in a finished job or a refund. Goes through the app's
   * own route so the sweep uses the same code, env and secrets as the webhook.
   */
  async scheduled(_controller, env, ctx) {
    const secret = env.CRON_SECRET;
    if (!secret) return;
    const origin = env.SITE_ORIGIN || DEFAULT_ORIGIN;
    const request = new Request(`${origin}/api/renders/sweep`, {
      method: "POST",
      headers: { Authorization: `Bearer ${secret}` },
    });
    ctx.waitUntil(
      Promise.resolve(handler.fetch(request, env, ctx)).then(async (res) => {
        if (!res.ok) console.error(`[cron] render sweep answered ${res.status}`);
      }),
    );
  },
};

export default worker;
